import {reviewTargets,needsReview,dimensionNames} from './review-core.mjs';
import {reproductionSummary} from './reproduction-core.mjs';
const status={pass:'符合',fail:'发现矛盾',unknown:'缺少证据',review_required:'需人工核对',supported:'获得支持',not_supported:'未获支持',inconclusive:'证据不足',completed:'已完成',failed:'失败',cancelled:'已停止',running:'执行中'};
const decisions={agree:'认可机器判断',disagree:'修正机器判断',needs_evidence:'补充证据后再审'};
const value=v=>typeof v==='number'&&Number.isFinite(v)?v.toFixed(6).replace(/\.?0+$/,''):'—';
export class ReviewView {
 constructor(parent){this.parent=parent;this.i=parent.i;this.contexts=new Map();this.views=new Map();this.message='';this.saving=false;}
 context(r,s){const key=(s.source||'unknown')+':'+(s.job?.id||r.run_id||'detached')+':'+(r.plan_sha256||'unknown')+':'+(r.source_manifest_sha256||'unknown');this.contexts.set(key,{r,s});if(!this.views.has(key))this.views.set(key,{tab:'overview',filter:'attention',selected:null,reviews:[],draft:{reviewer:'',reason:'',decision:'needs_evidence'}});const view=this.views.get(key);if(!view.loaded){try{const stored=JSON.parse(localStorage.getItem('articheck:review:'+key)||'[]');view.reviews=Array.isArray(stored)&&stored.length?stored:(s.reviews||[]);}catch{}view.loaded=true;}return {key,view};}
 render(r,s,e){const {key,view}=this.context(r,s),sum=reproductionSummary(r),targets=reviewTargets(r),pending=targets.filter(needsReview),source=s.source==='runtime'?'本地执行证据':s.source==='public_case'?'LIBLINEAR / news20':'导入报告 · 来源未核验';return `<section class="review-station" data-review-context="${e(key)}"><div class="review-heading"><div><h3>${source}</h3><p>${status[r.status]||e(r.status)} · ${sum.completed} / ${sum.expected??'—'} 次计划运行 · ${sum.stages} 个阶段</p></div><button class="btn text" data-review-export>导出证据包</button></div><div class="revision-ribbon"><span>计划 <code>${e(r.plan_sha256?.slice(0,12)||'未记录')}</code></span><span>代码清单 <code>${e(r.source_manifest_sha256?.slice(0,12)||'未记录')}</code></span><span>${e(r.finished_at?.slice(0,16).replace('T',' ')||r.created_at?.slice(0,16).replace('T',' ')||'时间未记录')}</span></div>${s.source==='public_case'?`<p class="review-notice">LIBLINEAR / news20：当前证据覆盖选定 CPU 实验。Figure 1、rcv1 与论文效率结论尚未覆盖。<a href="${e(r.provenance?.workflow_url||'#')}" target="_blank" rel="noopener">查看 CI 来源</a></p>`:s.source!=='runtime'?'<p class="review-notice">报告独立保存，不绑定当前论文，也不授权启动实验。人工批注只保存在当前浏览器。</p>':''}<div class="review-tabs" role="group" aria-label="实验证据视图">${[['overview','结果摘要'],['evidence',`审查队列 · ${pending.length} 项`],['trace','阶段轨迹'],['report','完整报告']].map(([id,label])=>`<button class="${view.tab===id?'active':''}" aria-pressed="${view.tab===id}" data-review-tab="${id}">${label}</button>`).join('')}</div>${this.message?`<p class="info-strip" role="status">${e(this.message)}</p>`:''}${view.tab==='overview'?this.overview(r,sum,pending,e):view.tab==='evidence'?this.queue(r,s,view,targets,e):view.tab==='trace'?this.trace(r,e):this.parent.legacyReport(r,s,sum,e)}</section>`;}
 overview(r,sum,pending,e){const rows=r.experiments.flatMap(exp=>Object.entries(exp.variants||{}).map(([id,v])=>({exp,id,v})));const reasons=['training','conclusion'].flatMap(k=>(r.level_requirements?.[k]||[]).map(text=>({k,text})));return `<div class="review-answer"><div><h3>${r.levels?.conclusion?'主要结论已有验收证据':'执行完成度与结论分开验收'}</h3><p>${r.levels?.conclusion?'继续检查原文覆盖、统计依据与人工复核意见。':`${sum.completed} 次运行完成；${pending.length} 条预审或统计记录待关注。`}</p></div><button class="btn" data-review-tab="evidence">开始审查</button></div><div class="review-overview-grid"><section class="review-metrics-panel"><div class="section-heading"><h3>重复实验指标</h3><span class="muted">原始数值 · 均值 ± 样本标准差</span></div><div class="metric-results">${rows.map(({exp,id,v})=>`<div class="metric-result-row"><div><strong>${e(id)}</strong><small>${e(exp.experiment_id)} · ${e(r.plan?.experiments?.find(x=>x.id===exp.experiment_id)?.metric?.key||'指标未声明')}</small></div><div class="metric-estimate"><strong>${value(v.mean)}</strong><small>± ${value(v.sample_std)} · n=${v.n}</small></div></div>`).join('')||'<p class="assessment-empty">尚无有效指标，查看阶段输出定位阻塞。</p>'}</div><dl class="review-measurements"><div><dt>实际耗时</dt><dd>${typeof r.elapsed_seconds==='number'?r.elapsed_seconds.toFixed(2)+' 秒':'—'}</dd></div><div><dt>子进程峰值 RSS</dt><dd>${r.measurement?.max_child_rss_bytes==null?'—':(r.measurement.max_child_rss_bytes/1024**2).toFixed(1)+' MiB'}</dd></div><div><dt>计算费用估计</dt><dd>${r.cost?.compute_estimate_usd==null?'单价未知':'$'+r.cost.compute_estimate_usd.toFixed(6)}</dd></div></dl></section><section class="review-gates"><h3>验收状态</h3>${[['run','计划执行'],['environment_rebuilt','环境重建'],['evaluation','评估复现'],['training','论文训练协议'],['conclusion','主要结论']].map(([id,label])=>`<div class="gate-row"><span>${label}</span><strong class="${r.levels?.[id]===true?'review-good':''}">${r.levels?.[id]===true?'证据满足':r.levels?.[id]===false?'尚未满足':'未独立判定'}</strong></div>`).join('')}<p class="small-note">环境重建是执行前提。未单独记录的评估层级保留未知。</p><button class="btn text" data-review-tab="report">查看验收条件与资源测量</button></section></div><section class="review-open-questions"><div class="section-heading"><h3>结论仍缺少的依据</h3><button class="btn text" data-review-tab="evidence">逐项对照证据</button></div>${reasons.length?`<ul>${reasons.slice(0,4).map(x=>`<li>${e(x.text)}</li>`).join('')}</ul>${reasons.length>4?`<p class="small-note">共 ${reasons.length} 项，完整报告保留全部条件。</p>`:''}`:'<p>查看机器检查与论文实验清单，确认本次结果的覆盖范围。</p>'}</section>`;}
 queue(r,s,v,targets,e){const rows=targets.filter(t=>v.filter==='stages'?t.kind==='阶段':t.kind!=='阶段'&&(v.filter==='all'||needsReview(t)));const selected=rows.find(t=>t.id===v.selected)||rows[0];const reviews=v.reviews.filter(x=>x.target_id===selected?.id);return `<div class="review-queue-layout ${v.detail?'show-review-detail':''}"><section class="review-queue"><div class="review-filter"><label for="review-filter">审查范围</label><select id="review-filter" data-review-filter><option value="attention" ${v.filter==='attention'?'selected':''}>需要关注</option><option value="all" ${v.filter==='all'?'selected':''}>全部核验与统计</option><option value="stages" ${v.filter==='stages'?'selected':''}>全部运行阶段</option></select></div><p class="small-note">${rows.length} 项 · 预审是执行前快照；运行后的环境和指标见验收状态。人工意见保留原判断</p>${rows.map(t=>`<button class="review-target ${selected?.id===t.id?'selected':''}" data-review-target="${e(t.id)}"><span class="review-target-state ${t.status==='fail'?'negative':''}">${status[t.status]||e(t.status)}</span><strong>${e(t.title)}</strong><small>${e(t.kind)}${t.dimension?' · '+e(dimensionNames[t.dimension]||t.dimension):''}</small></button>`).join('')||'<p class="assessment-empty">当前范围没有待审记录。可切换至全部核验与统计。</p>'}</section><section class="review-detail">${selected?`<button class="btn text review-back" data-review-back>返回审查队列</button><div class="section-heading"><h3>${e(selected.title)}</h3><span>${status[selected.status]||e(selected.status)}</span></div><p class="small-note">${e(selected.code||selected.id)}</p><p class="review-detail-reason">${e(selected.detail||'未提供说明')}</p>${selected.evidence?.quote?`<blockquote class="paper-citation"><p>${e(selected.evidence.quote)}</p><cite>PDF 第 ${e(selected.evidence.page??'未知')} 页</cite></blockquote>`:''}<details open><summary>原始证据与定位</summary><pre>${e(JSON.stringify(selected.evidence,null,2))}</pre></details><form class="review-decision" data-review-form><h3>人工复核意见</h3><p class="small-note">${s.source==='runtime'&&s.job?'具名意见追加到本机任务记录；不覆盖机器结论。':'此归档报告的批注保存在当前浏览器，可随证据包导出。'}</p><div class="form-grid"><div class="field"><label for="review-person">审核人</label><input id="review-person" name="reviewer" maxlength="100" required value="${e(v.draft.reviewer)}"></div><div class="field"><label for="review-decision">复核判断</label><select id="review-decision" name="decision">${Object.entries(decisions).map(([id,label])=>`<option value="${id}" ${v.draft.decision===id?'selected':''}>${label}</option>`).join('')}</select></div></div><div class="field"><label for="review-reason">依据与证据位置</label><textarea id="review-reason" name="reason" maxlength="5000" required placeholder="原文页码、代码路径或运行输出，以及判断理由">${e(v.draft.reason)}</textarea></div><button class="btn" type="submit" ${this.saving||s.source==='runtime'&&s.job&&['queued','running'].includes(s.job.status)?'disabled':''}>${this.saving?'正在保存…':s.source==='runtime'&&s.job&&['queued','running'].includes(s.job.status)?'任务结束后可保存复核':'保存本条复核'}</button>${s.source==='runtime'&&s.job?'<button class="btn text" type="button" data-review-load>读取本机复核记录</button>':''}<input type="hidden" name="target_id" value="${e(selected.id)}"></form><div class="review-decisions">${reviews.map(x=>`<article><strong>${e(x.reviewer)} · ${decisions[x.decision]||e(x.decision)}</strong><p>${e(x.reason)}</p><small>${e(x.created_at?.slice(0,16).replace('T',' '))} · ${x.storage==='browser'?'浏览器批注':'本机追加记录'}</small></article>`).join('')}</div>`:'<p class="assessment-empty">选中一项，核对原文与机器证据。</p>'}</section></div>`;}
 trace(r,e){return `<section class="review-trace"><h3>冻结计划的执行轨迹</h3><p class="small-note">按实验、方法和种子记录实际阶段。完整实验执行器按预注册计划运行。</p>${r.runs.map((run,ri)=>`<details class="trace-run"><summary>${e(run.experiment)} / ${e(run.variant)} / seed ${run.seed}<span>${status[run.status]||e(run.status)} · 指标 ${value(run.metric)}</span></summary>${run.stages.map((st,si)=>`<details class="trace-stage"><summary><strong>${e(st.id)}</strong><span>${status[st.status]||e(st.status)} · ${typeof st.elapsed_seconds==='number'?st.elapsed_seconds.toFixed(2)+' 秒':'—'}</span></summary><p>输入 → 输出文件与指纹见下方记录；退出码 ${e(st.returncode??'未知')}</p><pre>${e(JSON.stringify(st,null,2))}</pre><button class="btn" data-review-stage-review="stage:${ri}:${si}">审查此阶段</button></details>`).join('')}</details>`).join('')||'<p class="assessment-empty">尚无阶段记录。</p>'}</section>`;}
 bind(){document.addEventListener('input',event=>{const form=event.target.closest('[data-review-form]'),host=event.target.closest('[data-review-context]');if(form&&host&&this.views.has(host.dataset.reviewContext)){const v=this.views.get(host.dataset.reviewContext);if(['reviewer','reason','decision'].includes(event.target.name))v.draft[event.target.name]=event.target.value;}});document.addEventListener('change',event=>{if(!event.target.matches('[data-review-filter]'))return;const key=event.target.closest('[data-review-context]').dataset.reviewContext;this.views.get(key).filter=event.target.value;this.i.h.render();});document.addEventListener('click',async event=>{const el=event.target.closest('[data-review-tab],[data-review-target],[data-review-back],[data-review-export],[data-review-load],[data-review-stage-review]');if(!el)return;const host=el.closest('[data-review-context]');if(!host)return;const key=host.dataset.reviewContext,{r,s}=this.contexts.get(key),v=this.views.get(key);this.message='';try{if(el.dataset.reviewTab)v.tab=el.dataset.reviewTab;if(el.dataset.reviewStageReview){v.tab='evidence';v.filter='stages';v.selected=el.dataset.reviewStageReview;v.detail=true;}if(el.dataset.reviewTarget){v.selected=el.dataset.reviewTarget;v.detail=true;v.draft.reason='';}if(el.hasAttribute('data-review-back'))v.detail=false;if(el.hasAttribute('data-review-export'))this.i.h.download('articheck-evidence-review.json',JSON.stringify({format:'articheck-evidence-review-v1',source:s.source,report:r,reviews:v.reviews},null,2));if(el.hasAttribute('data-review-load'))v.reviews=(await this.i.h.request('/api/reproduction/runs/'+s.job.id+'/reviews')).items;}catch(error){this.message=error.message;}this.i.h.render();});document.addEventListener('submit',async event=>{if(!event.target.matches('[data-review-form]'))return;event.preventDefault();const key=event.target.closest('[data-review-context]').dataset.reviewContext,{r,s}=this.contexts.get(key),v=this.views.get(key),body=Object.fromEntries(new FormData(event.target));this.saving=true;try{if(!body.reviewer.trim()||!body.reason.trim())throw Error('填写审核人与证据依据');let row;if(s.source==='runtime'&&s.job&&this.i.h.mode()==='runtime')row=await this.i.h.request('/api/reproduction/runs/'+s.job.id+'/reviews',{...body,plan_sha256:r.plan_sha256});else{row={...body,plan_sha256:r.plan_sha256,run_id:r.run_id,created_at:new Date().toISOString(),storage:'browser'};}v.reviews.push(row);v.draft.reason='';if(row.storage==='browser'){localStorage.setItem('articheck:review:'+key,JSON.stringify(v.reviews));}this.message='复核意见已追加，机器原始判断保持可查。';}catch(error){this.message=error.message;}finally{this.saving=false;this.i.h.render();}});}
}
